head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
// jackal_11.05.12

scwin.vScrenID = "ULDSTF08031.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EN; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 
scwin.fr_MktId = $c.lce.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // jackal_11.05.12 상장종목 여부 체크 추가

scwin.fn_search = function() {
    var url = "/etn/EtnMktAct.do?method=searchEtnAdministrativeIssue";
    url += "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    if (rdo_ISUR_CD_1.getValue() == "1") {
        url += "&DIV_IDX=" + DIV_ETN_IDX_ADMISU_LIST_ISU + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + txb_ISU_CD.getValue();
    } else if (rdo_ISUR_CD_2.getValue() == "1") {
        if (cmb_ISUR_CD.getSelectedIndex() == 0) {
            url += "&DIV_IDX=" + DIV_ETN_IDX_ADMISU_LIST_ALL + "&TRS_IDX=" + TRS_IDX_SELECT + "&GUBUN_CD=ETN";
        } else {
            url += "&DIV_IDX=" + DIV_ETN_IDX_ADMISU_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal + "&GUBUN_CD=ETN";
        }
    }
    //alert(url);
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd_List);
};


// dialog 호출용 함수
// 예비심사청구제출기관 호출관련
scwin.fn_GetParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_ISU_NM); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};
scwin.fn_SetParIsur = function(arrPar) {
    var dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn == "Y") {
        scwin.fn_changeRadioBtn(1);
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        //txb_ISU_NM.value = arrPar[0].ISU_KOR_NM;
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_ABBRV);
        scwin.vIsurCd = arrPar[0].ISUR_CD;
    }
    scwin.fn_search();
    //jackal_11.05.12
    // 삭제 종목인 경우 모든 버튼 discable
    scwin.vLIST_STAT_CD = arrPar[0].LIST_STAT_CD;
    if (scwin.vLIST_STAT_CD == "D") {
        img_Regist.setDisabled(true);
        img_Regist.src = "../img/btn_new_d.gif";
    } else {
        img_Regist.setDisabled(false);
        img_Regist.src = "../img/btn_new.gif";
    }
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    if (rdo_ISUR_CD_1.getValue() == "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 종목코드명
        arrPar[6] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[7] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_ISUR_CD_2.getValue() == "1") {
        if (cmb_ISUR_CD.getSelectedIndex() == 0) {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            arrPar[6] = dts.getCellData(dts.getRowPosition(), "ISU_CD"); // 종목코드값
            arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = scwin.vIsurCd; // 발행기관코드값
            arrPar[1] = dts.getCellData(dts.getRowPosition(), "COM_NM"); // 발행기관명
            //arrPar[1] = cmb_ISUR_CD.Text; // 발행기관명
            arrPar[6] = dts.getCellData(dts.getRowPosition(), "ISU_CD"); // 종목코드값
            arrPar[7] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts.getCellData(dts.getRowPosition(), "ADMISU_DESIGN_BZ_TP_CD"); // 거래정지지정및해제구분코드
    arrPar[8] = dts.getCellData(dts.getRowPosition(), "ADMISU_DESIGN_BZ_PROCS_NO"); // 지정업무처리번호

    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    if (rdo_ISUR_CD_1.getValue() == "1") {
        arrPar[0] = scwin.vIsurCd; // 발행기관코드값
        arrPar[1] = txb_ISU_NM.getValue(); // 발행기관명
        arrPar[6] = txb_ISU_CD.getValue(); // 종목코드값
        arrPar[7] = "1"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

    } else if (rdo_ISUR_CD_2.getValue() == "1") {
        if (cmb_ISUR_CD.getSelectedIndex() == 0) {
            arrPar[0] = ""; // 발행기관코드값
            arrPar[1] = ""; // 발행기관명
            arrPar[6] = ""; // 종목코드값
            arrPar[7] = "3"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        } else {
            arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
            arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
            arrPar[6] = ""; // 종목코드값
            arrPar[7] = "2"; // 선택 구분(1:종목, 2:발행회사, 3:전체)

        }
    }
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = cmb_RegistTyp.BindColVal; // 지정및해제구분코드
    arrPar[8] = ""; // 지정업무처리번호

};
scwin.fn_new_create_frame = async function(arg) {
    /*
    0:관리종목지정
    4:관리종목지정해제
    */
    switch (arg) {
        case "0":
            await $c.frame.CreateDialogFrame("DLG_0", "../etn/ULDSTF08032_new.gfm", $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정", 200, 50, 750, 450, "window");
            break;
        case "4":
            await $c.frame.CreateDialogFrame("DLG_2", "../etn/ULDSTF08033_new.gfm", $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정 해제", 200, 50, 755, 595, "window");
            break;
    }
    cmb_RegistTyp.setSelectedIndex(0);
};
scwin.fn_newpre_create_frame = async function(arg) {
    /*
    0:관리종목지정
    1:관리종목사유변경
    4:관리종목지정해제
    */
    switch (arg) {
        case "0":
            await $c.frame.CreateDialogFrame("DLG_0", "../etn/ULDSTF08032.gfm", $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정", 200, 50, 720, 450, "window");
            break;
        case "1":
            await $c.frame.CreateDialogFrame("DLG_1", "../etn/ULDSTF08034.gfm", $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정 사유변경", 200, 5, 720, 680, "window");
            break;
        case "4":
            await $c.frame.CreateDialogFrame("DLG_2", "../etn/ULDSTF08033.gfm", $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 관리종목지정 해제", 200, 50, 725, 600, "window");
            break;
    }
    cmb_RegistTyp.setSelectedIndex(0);
};
scwin.fn_get_isurcode = function() {
    //etn발행사
    dts_EtnInst.DataID = "/etn/EtnCodeAct.do?method=listIsurCd&For=R";
    dts_EtnInst.Reset();
};
scwin.fn_changeRadioBtn = function(idx) {
    if (idx == "1") {
        cmb_ISUR_CD.setSelectedIndex(0);
        rdo_ISUR_CD_1.setValue("1");
        rdo_ISUR_CD_2.setValue("2");
    } else if (idx == "2") {
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        rdo_ISUR_CD_1.setValue("2");
        rdo_ISUR_CD_2.setValue("1");
    }
};
scwin.img_Search_onclick = function() {
    if (rdo_ISUR_CD_1.getValue() == "1") {
        if (txb_ISU_CD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
    }
    scwin.fn_search();
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    //FillGridHeaderTotalCnt(rowcount, panel_page);
    txb_TotCnt.setValue("총건수 : " + rowcount);
    dts.setRowPosition(rowcount, 0);
    $c.cm.CloseWin(rowcount, grd_List);
};
scwin.img_Excel_onclick = function() {
    if (dts.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "괸리종목지정내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.img_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.btn_iSU_CD_onclick = function() {
    scwin.fn_GetPar = fn_GetParIsur;
    scwin.fn_SetPar = fn_SetParIsur;
    //fn_PopFindIsu(fr_SecuGrpId);
    //fn_PopFindIsuAll(fr_SecuGrpId);		// jackal_11.05.12
    $c.lce.fn_PopFindEtnIsuAll(scwin.fr_SecuGrpId);
};
scwin.img_Regist_onclick = function() {
    if (rdo_ISUR_CD_1.getValue() == "1") {
        if (txb_ISU_CD.getValue() == "") {
            $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
            return true;
        }
        if (cmb_RegistTyp.BindColVal == "4") {
            $c.win.alert("관리종목지정 세부화면에서 해제 해주시기 바랍니다.");
            return true;
        }
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    if (rdo_ISUR_CD_2.getValue() == "1") {
        scwin.fn_new_create_frame(cmb_RegistTyp.BindColVal);
    } else {
        scwin.fn_newpre_create_frame(cmb_RegistTyp.BindColVal);
    }
    //fn_newpre_create_frame("0" );

};
scwin.grd_List_OnDblClick = function(row, colid) {
    // jackal_11.05.12 삭제종목인 경우 팝업 금지
    if (rdo_ISUR_CD_1.getValue() == "1") {
        if (scwin.vLIST_STAT_CD == "D") {
            return true;
        }
    }
    scwin.vIsurCd = dts.getCellData(dts.getRowPosition(), "ISUR_CD");
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;

    // 거래정지지정및해제구분코드 값 넘겨야함
    scwin.fn_newpre_create_frame(dts.getCellData(dts.getRowPosition(), "ADMISU_DESIGN_BZ_TP_CD"));
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
    rdo_ISUR_CD_1.setValue("1");
    scwin.fn_get_isurcode();
};
scwin.rdo_ISUR_CD_1_OnClick = function() {
    //rdo_ISUR_CD_2.CodeValue ="2";
    scwin.fn_changeRadioBtn(1);
};
scwin.rdo_ISUR_CD_2_OnClick = function() {
    //rdo_ISUR_CD_1.CodeValue ="2";
    scwin.fn_changeRadioBtn(2);
    scwin.fn_search();
};
scwin.cmb_ISUR_CD_OnSelChange = function() {
    scwin.fn_changeRadioBtn(2);
    //if( rdo_ISUR_CD_2.CodeValue == "1" && cmb_ISUR_CD.index != 0 ) {
    scwin.fn_search();
    //}

};
